-- Do not apply automatically; Aaron reviews and runs this migration.

create table if not exists public.spelling_curriculum_words (
  id uuid primary key default gen_random_uuid(),
  word text not null,
  nature text not null,
  frequency integer not null,
  strand text not null check (strand in ('lexical', 'invariable')),
  tier_id text not null,
  language text not null default 'fr-FR',
  echelon integer,
  source_name text not null,
  source_citation text not null,
  source_metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique (language, strand, tier_id, word, nature)
);

create index if not exists spelling_curriculum_words_lookup_idx
  on public.spelling_curriculum_words (language, strand, tier_id, frequency);

create index if not exists spelling_curriculum_words_word_idx
  on public.spelling_curriculum_words (language, word);

